function last(arr, x) {
  let left = 0;
  let right = arr.length - 1;

  while (left <= right) {
    const mid = Math.floor((left + right) / 2);

    if (arr[mid] === x) {
      // If the element is found, move the left pointer to the right
      left = mid + 1;
    } else if (arr[mid] < x) {
      // If the element is greater than x, move the left pointer to the right
      left = mid + 1;
    } else {
      // If the element is less than x, move the right pointer to the left
      right = mid - 1;
    }
  }

  // Return the last position of the element
  return left - 1;
}

