function simplify(x, n) {
  const [numeratorX, denominatorX] = x.split('/');
  const [numeratorN, denominatorN] = n.split('/');

  // Calculate the product of the numerators and denominators separately
  const numeratorProduct = parseInt(numeratorX) * parseInt(numeratorN);
  const denominatorProduct = parseInt(denominatorX) * parseInt(denominatorN);

  // Check if the product is a whole number
  return numeratorProduct % denominatorProduct === 0;
}

function rotate_right(list, m) {
  let n = list.length;
  let temp = new Array(m);

  // Copy the last m elements to the temporary array
  for (let i = 0; i < m; i++) {
    temp[i] = list[n - m + i];
  }

  // Shift the remaining elements of the original array to the left by m positions
  for (let i = n - m; i < n; i++) {
    list[i - m] = list[i];
  }

  // Copy the temporary array back to the original array
  for (let i = 0; i < m; i++) {
    list[i] = temp[i];
  }
}

function rotate_right(list, m) {
  let n = list.length;
  if (m >= n) {
    m %= n; // Handle cases where m is greater than or equal to the length of the array
  }

  let temp = new Array(m);

  // Copy the last m elements to the temporary array
  for (let i = 0; i < m; i++) {
    temp[i] = list[n - m + i];
  }

  // Shift the remaining elements of the original array to the left by m positions
  for (let i = n - m; i < n; i++) {
    list[i - m] = list[i];
  }

  // Copy the temporary array back to the original array
  for (let i = 0; i < m; i++) {
    list[i] = temp[i];
  }
}

