function catalan_number(num) {
    if (num <= 1) return 1;
    let catalan = new Array(num + 1).fill(0);
    catalan[0] = 1;
    catalan[1] = 1;

    for (let i = 2; i <= num; i++) {
        catalan[i] = 0;
        for (let j = 0; j < i; j++) {
            catalan[i] += catalan[j] * catalan[i - j - 1];
        }
    }

    return catalan[num];
}

