function is_nested(string) {
    let balance = 0;
    let hasNested = false;

    for (let i = 0; i < string.length; i++) {
        if (string[i] === '[') {
            balance++;
            if (balance > 1 && !hasNested) {
                hasNested = true;
            }
        } else if (string[i] === ']') {
            balance--;
            if (balance < 0) {
                return false; // A closing bracket appears before a matching opening bracket
            }
            if (balance === 0 && hasNested) {
                return true; // Found a nested subsequence
            }
        }
    }

    return false;
}

function next_smallest_palindrome(num) {
  // Convert number to string to easily manipulate digits
  let str = num.toString();

  // Find the largest non-palindromic prefix of the number
  let i = 0;
  while (i < str.length && str[i] === str[str.length - i - 1]) {
    i++;
  }

  // If no such prefix exists, return the next palindrome by appending '9'
  if (i === 0) {
    return num + 1;
  }

  // Create the largest palindromic suffix of the number
  let suffix = str.substring(i);
  let reversed_suffix = suffix.split('').reverse().join('');

  // Construct the next smallest palindrome by appending the reversed suffix to the prefix
  let next_palindrome = str.substring(0, i) + reversed_suffix;

  return parseInt(next_palindrome);
}

