function count_Occurrence(tup, lst) {
  const occurrenceCount = {};

  for (const element of tup) {
    if (occurrenceCount[element] === undefined) {
      occurrenceCount[element] = 0;
    }
    occurrenceCount[element]++;
  }

  for (const element of lst) {
    if (occurrenceCount[element] !== undefined) {
      occurrenceCount[element]--;
    }
  }

  return Object.fromEntries(Object.entries(occurrenceCount).filter(([key, value]) => value === 0));
}

