function max_sum_increasing_subseq(a, n, index, k) {
    if (index >= n || k >= n) return 0;

    let include = a[index] + max_sum_increasing_subseq(a, n, index + 1, k);
    let exclude = max_sum_increasing_subseq(a, n, index + 1, k);

    return Math.max(include, exclude);
}

function max_sum_increasing_subseq(a, n, index, k) {
