function heap_queue_largest(nums, n) {
  // Convert the array into a max-heap using the heapify method
  for (let i = Math.floor(nums.length / 2 - 1); i >= 0; i--) {
    heapify(nums, nums.length, i);
  }

  // Extract the n largest elements from the heap
  let result = [];
  for (let i = 0; i < n; i++) {
    result.push(nums[0]);
    swap(nums, 0, nums.length - 1 - i);
    heapify(nums, nums.length - 1 - i, 0);
  }

  // Sort the result in descending order
  result.sort((a, b) => b - a);

  return result;
}

