  let right = arr.length - 1;

  while (left < right) {
    let mid = Math.floor((left + right) / 2);

    // If the middle element is odd, it means the element to be found is in the right half
    if (mid % 2 !== 0) {
      // Check if the element at the middle is equal to the element before it
      if (arr[mid] === arr[mid - 1]) {
        left = mid + 1;
      } else {
        right = mid - 1;
      }
    } else {
      // If the middle element is even, it means the element to be found is in the left half
      if (arr[mid] === arr[mid + 1]) {
        left = mid + 2;
