  memo.set(0, 0);
  memo.set(1, 1);

  function helper(num) {
    if (memo.has(num)) return memo.get(num);

    const sum = Math.max(
      helper(Math.floor(num / 2)) + helper(Math.floor(num / 3)) + helper(Math.floor(num / 4)) + helper(Math.floor(num / 5)),
      num
    );

    memo.set(num, sum);
    return sum;
  }

  return helper(n);
}

