function max_sum(arr) {
  let n = arr.length;
  let dp1 = new Array(n).fill(0);
  let dp2 = new Array(n).fill(0);

  // Fill dp1
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < i; j++) {
      if (arr[i] > arr[j] && dp1[i] < dp1[j] + arr[i]) {
        dp1[i] = dp1[j] + arr[i];
      }
    }
  }

  // Fill dp2
  for (let i = n - 1; i >= 0; i--) {
    for (let j = i + 1; j < n; j++) {
      if (arr[i] > arr[j] && dp2[i] < dp2[j] + arr[i]) {
        dp2[i] = dp2[j] + arr[i];
      }
    }
  }

  // Find the maximum sum of bitonic subsequence
  let max_sum = 0;
  for (let i = 0; i < n; i++) {
    max_sum = Math.max(max_sum, dp1[i] + dp2[i] - arr[i]);
  }

  return max_sum;
