function rgb_to_hsv(r, g, b) {
  // Normalize RGB values to the range [0, 1]
  r /= 255;
  g /= 255;
  b /= 255;

  // Find the maximum and minimum values in RGB
  let max = Math.max(r, g, b);
  let min = Math.min(r, g, b);

  // Calculate the value (V)
  let v = max;

  // Calculate the saturation (S)
  let s = max === 0 ? 0 : (v - min) / v;

  // Calculate the hue (H)
  let h;
  if (max === r) {
    h = (g - b) / (max - min);
  } else if (max === g) {
    h = 2 + (b - r) / (max - min);
  } else {
    h = 4 + (r - g) / (max - min);
  }

  // Normalize the hue to be in the range [0, 360]
  h *= 60;
  if (h < 0) {
    h += 360;
  }

  return { h: h, s: s, v: v };
}

