function rearrange_bigger(n) {
  // Convert the number to an array of its digits
  const digits = n.toString().split('');

  // Find the first digit from the right that is smaller than the digit immediately to its right
  let i;
  for (i = digits.length - 2; i >= 0; i--) {
    if (digits[i] < digits[i + 1]) break;
  }

  // If no such digit is found, return -1 as it's not possible to rearrange to form a bigger number
  if (i === -1) return -1;

  // Find the smallest digit on the right side of i that is greater than digits[i]
  let j;
  for (j = digits.length - 1; j > i; j--) {
    if (digits[j] > digits[i]) break;
  }

  // Swap these two digits
  [digits[i], digits[j]] = [digits[j], digits[i]];

  // Sort the remaining digits to form the smallest possible number
  digits.sort((a, b) => a - b);

  // Combine the digits back into a single number
  return parseInt(digits.join(''));
}

