function maxAverageOfPath(cost) {
    const n = cost.length;
    let dp = Array.from({ length: n }, () => Array(n).fill(0));

    // Initialize the first cell of the DP table
    dp[0][0] = cost[0][0];

    // Fill the first row
    for (let i = 1; i < n; i++) {
        dp[0][i] = dp[0][i - 1] + cost[0][i];
    }

    // Fill the first column
    for (let j = 1; j < n; j++) {
        dp[j][0] = dp[j - 1][0] + cost[j][0];
    }

    // Fill the rest of the DP table
    for (let i = 1; i < n; i++) {
        for (let j = 1; j < n; j++) {
            dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost[i][j];
        }
    }

    // Calculate the maximum average
    let maxAverage = -Infinity;
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            const totalCost = dp[i][j];
            const pathLength = i + j + 1;
            const average = totalCost / pathLength;
            maxAverage = Math.max(maxAverage, average);
        }
    }

    return maxAverage;
}

