  let sumRow = 0, sumCol = 0;

  // Calculate the sum of each row and column
  for (let i = 0; i < n; i++) {
    sumRow += my_matrix[i][i];
    sumCol += my_matrix[i][n - 1 - i];

    for (let j = 0; j < n; j++) {
      if (i === j) {
        continue;
      }
      sumRow += my_matrix[i][j];
      sumCol += my_matrix[j][i];
    }
  }

  // Check if all rows and columns have the same sum
  return sumRow === sumCol && sumRow === n * (n + 1) / 2;
}

