function eulerian_num(n, m) {
  if (m > n || m < 0 || n < 0) return 0;

  const memo = new Array(n + 1).fill(null).map(() => new Array(m + 1).fill(0));

  for (let i = 0; i <= n; i++) {
    for (let j = 0; j <= m; j++) {
      if (i === 0) {
        memo[i][j] = 1;
      } else if (j === 0) {
        memo[i][j] = 1;
      } else if (j > i) {
        memo[i][j] = 0;
      } else {
        memo[i][j] = (i - j) * (memo[i - 1][j - 1] + memo[i - 1][j]);
      }
    }
  }

  return memo[n][m];
}

